import type { VmGroupConfig } from "./VmGroupConfig.js";
import type { VmUserAccountConfig } from "./VmUserAccountConfig.js";
/**
 * Initial Linux-style credentials and account record for processes in a VM.
 */
export type VmUserConfig = {
    uid?: number;
    gid?: number;
    euid?: number;
    egid?: number;
    username?: string;
    homedir?: string;
    shell?: string;
    gecos?: string;
    groupName?: string;
    supplementaryGids?: Array<number>;
    accounts?: Array<VmUserAccountConfig>;
    groups?: Array<VmGroupConfig>;
};
